service.method:

SELECT
	HOUSE_CODE
	,COMPANY_CODE
	,USER_ID
FROM
	SUSMT WITH(NOLOCK)
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
	AND COMPANY_CODE = ${COMPANY_CODE}
	AND USER_ID = ${USER_ID}


INSERT
  INTO SPMGT
     ( HOUSE_CODE       
      ,COMPANY_CODE     
      ,CONT_NO          
      ,CONT_GL_SEQ      
      ,SEQ              
      ,ADD_DATE         
      ,ADD_TIME         
      ,USER_COMPANY_CODE
      ,USER_ID          
      ,ACTION           
      ,IP
     )
VALUES
     ( ${session.HOUSE_CODE}       
      ,${session.COMPANY_CODE}     
      ,${SMR_NUMBER}        
      ,'1'      
      ,(SELECT COUNT(*) + 1
          FROM SPMGT InPMGT WITH(NOLOCK)
         WHERE InPMGT.HOUSE_CODE   = ${session.HOUSE_CODE}
           AND InPMGT.COMPANY_CODE = ${session.COMPANY_CODE}
           AND InPMGT.CONT_NO      = ${SMR_NUMBER}
           AND InPMGT.CONT_GL_SEQ  = '1'
       )
      ,${current.DATE}         
      ,${current.TIME}         
      ,${session.COMPANY_CODE}
      ,${CONFIRM_USER_ID}
      ,${ACTION}           
      ,${IP}
     )


DELETE
  FROM SPMGT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${session.COMPANY_CODE}
   AND CONT_NO      = ${SMR_NUMBER}
   AND CONT_GL_SEQ  = '1'
